nta.declaration:
/************************************************************
 *                     CONSTANTS
 ************************************************************/
//---SPACE

const int WIDTH  = 18;
const int HEIGHT = 13;
const int BORDER_DELAY = 2;

const int MAX_PER_ROW = 4;
const int NUM_MOVING_ROWS = 12;
const int TOTAL_LOOP = WIDTH + BORDER_DELAY;

//frog starts from this point on the map
const int START_X= 9;
const int START_Y = 0;

//--- GENERAL

const int MAX_LIVES = 5;
const int NUM_HOME_BAYS = 5;

const int BAY_SCORE = 5; 
const int LEVEL_SCORE = 100; 
const int MOVE_SCORE = 1;

const int BAY_BLOCK_SIZE = 4;
const int BAY_WIDTH = 2;

//--- TIME

const int TICK_PERIOD = 1;
const int TIME_UNITS_PER_SECOND = 10;
const int RESPAWN_DELAY = 20;         // 2 s
const int INITIAL_TIME_LIMIT = 300;   // 30 s
const int TICKS_BTW_MOVES = 1;

const int DIVE_THRESHOLD_ABOVE = 25;
const int DIVE_THRESHOLD_SUBMERGED = 10;

const int TRUCK_SPEED = 7; 

// For locations that only receive a broadcast (their sole outgoing edge is tick? with no separate spontaneous edge), 
//the rate is cosmetic — it never causes a spontaneous firing because the location can only leave when someone else emits tick!.
const int dummyExpRate = 1;
/************************************************************
 *                    ENUMERATIONS
 ************************************************************/

typedef int[0,3] TileType;

const TileType SAFE  = 0;
const TileType ROAD  = 1;
const TileType RIVER = 2;
const TileType HOME  = 3;

typedef int[0,4] ObjectType;

const ObjectType VEHICLE        = 0;
const ObjectType TRUCK          = 1;
const ObjectType LOG            = 2;
const ObjectType TURTLE         = 3;
const ObjectType DIVING_TURTLE  = 4;

typedef int[0,3] Direction;
const Direction UP  = 0;
const Direction DOWN  = 1;
const Direction LEFT  = 2;
const Direction RIGHT  = 3;


/************************************************************
 *              IMMUTABLE OBJECT DESCRIPTION
 ************************************************************/
/**
 * Immutable description of a moving object group.
 *
 * Stores the properties shared by all objects in a row, including movement
 * direction, object type, object size, initial positions, and special states
 * such as diving turtles.
 */
typedef struct
{
    int row;                    // y coordinate
    int size;                   // vehicle length
    int speed;                  // movement period
    bool moveLeft;               // if true, then the object moves from right to left

    ObjectType type;
    bool diving;          // only turtles may dive
    int numObjects;
    int initialX[MAX_PER_ROW];
} RowInfo;


/************************************************************
 *              MUTABLE OBJECT STATE
 ************************************************************/
/**
 * Mutable runtime state of a moving object group.
 *
 * Stores the current horizontal position of each object. Values are updated
 * during gameplay while the corresponding RowInfo data remains unchanged.
 */
typedef struct
{
    int x[MAX_PER_ROW];
} RowState;

/************************************************************
 *                GAME STATE VARIABLES
 ************************************************************/

int[0, TOTAL_LOOP-1] frog_x = START_X;
int[0, HEIGHT-1] frog_y  = START_Y;

// max reachable: 100 (level) + 25 (5 bays*5) + no more than 165 *5 (moves up) = 950
int [0, 1000] score = 0; 
int[0, MAX_LIVES] lives = MAX_LIVES;

bool bayOccupied[NUM_HOME_BAYS];

int[0, INITIAL_TIME_LIMIT] globalTick = 0;
int[0, INITIAL_TIME_LIMIT] currentLevelTimeLimit = INITIAL_TIME_LIMIT;

int [1, 500] level = 1;

/************************************************************
 *                 STATIC MAP
 ************************************************************/
/**
 * Static terrain layout of the game board.
 *
 * Each row defines the terrain type used for collision detection and movement
 * rules. The map separates safe areas, roads, rivers, and home locations.
 */
const TileType map[HEIGHT] =
{
    SAFE,   // 0
    ROAD,   // 1
    ROAD,   // 2
    ROAD,   // 3
    ROAD,   // 4
    ROAD,   // 5
    SAFE,   // 6
    RIVER,  // 7
    RIVER,  // 8
    RIVER,  // 9
    RIVER,  //10
    RIVER,  //11
    HOME    //12
};

const int rowFirstGroup[HEIGHT] =
{
    -1, // 0 SAFE
     0, // 1
     1, // 2
     2, // 3
     3, // 4
     4, // 5
    -1, // 6 SAFE
     5, // 7
     7, // 8
     8, // 9
     9, //10
    11, //11
    -1  //12 HOME
};
/************************************************************
 *              SYNCHRONIZATION CHANNELS
 ************************************************************/

broadcast chan tick;
broadcast chan timeOut;

broadcast chan frogInitPosition;

broadcast chan reachBay;
broadcast chan loseOneLife;

/************************************************************
 *            OBJECT DECLARATIONS
 ************************************************************/
/**
 * Immutable configuration table for all moving object groups.
 *
 * Each entry defines one group of moving entities, including position,
 * movement speed, direction, object type, and initial placement. Runtime
 * positions are stored separately in rowState.
 */
const RowInfo rowInfo[NUM_MOVING_ROWS] =
{
    // row,size,speed,left,type,diving,numObj,{positions}

    {1,1,3,true ,VEHICLE,false,2,{4,14,0,0}},
    {2,1,10,false,VEHICLE,false,2,{2,11,0,0}},
    {3,1,5,true ,VEHICLE,false,4,{4,8,13,17}},
    {4,1,4,false,VEHICLE,false,2,{2,10,0,0}},
    {5,2,TRUCK_SPEED,true ,TRUCK,false,2,{4,15,0,0}},

    // Row 7
    {7,5,6,true ,TURTLE,false,1,{5,0,0,0}},
    {7,5,6,true ,TURTLE ,true ,1,{13,0,0,0}},

    // Row 8
    {8,3,2,false,LOG,false,3,{7,11,15,0}},

    // Row 9
    {9,9,7,false,LOG,false,1,{3,0,0,0}},

    // Row10
    {10,3,2,true,TURTLE,false,1,{1,0,0,0}},
    {10,3,2,true,TURTLE ,true ,1,{9,0,0,0}},

    // Row11
    {11,5,2,false,LOG,false,2,{1,11,0,0}}
};

/**
 * Runtime positions of all moving object groups.
 *
 * This array changes during gameplay as objects move, while rowInfo remains constant.
 */
RowState rowState[NUM_MOVING_ROWS];

// Only meaningful for diving turtle rows.Other rows ignore this value.
bool isSubmerged = false;

//------------------------------------------------------INIT---------------------------

/**
 * Initializes the runtime positions of all moving objects.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Copies the initial positions stored in the immutable row descriptions into
 * the mutable row state array. Also resets the diving state used by turtle rows.
 */
void initializeRows()
{
    int y, obj;

    for(y = 0; y < NUM_MOVING_ROWS; y++)
    {
        for(obj = 0; obj < rowInfo[y].numObjects; obj++)
        {
            rowState[y].x[obj] = rowInfo[y].initialX[obj];
        }
    }

}

/**
 * Resets the occupancy state of all home bays.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Iterates through every home bay and marks it as empty. This function is
 * called when starting a new level to restore the initial game state.
 */
void clearHomeBays()
{
    int i;

    for(i = 0; i < NUM_HOME_BAYS; i++)
        bayOccupied[i] = false;
}

/**
 * Moves the frog back to its initial starting position.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Updates the frog coordinates using the predefined starting position constants. 
 * This function is used after losing a life and after completing a level.
 */
void frogReposition()
{
    frog_x = START_X;
    frog_y = START_Y;
}

/**
 * Resets all level-specific variables and prepares a new level.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Clears occupied home bays, places the frog at its initial position, 
 * and resets the level timer counter while keeping global game progress values.
 */
void startNewLevel()
{
    clearHomeBays();

    frogReposition();

    globalTick = 0;
}

/**
 * Completes the current level and prepares the next one.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Adds the level completion reward to the score and restores all level dependent variables by starting a new level.
 */
void finishCurrentLevel()
{
    level++;

    if(currentLevelTimeLimit > 20)
        currentLevelTimeLimit -= 20;     // 2 seconds that have to be removed according to the assignment rules

    startNewLevel();
}

/**
 * Initializes the complete game state before gameplay begins.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Initializes moving objects, resets lives and score, and starts the first level with all default values.
 */
void initializeGame()
{
    initializeRows();

    lives = MAX_LIVES;

    score = 0;

    level = 1;

    startNewLevel();
}



/**
 * Removes one player life and resets the frog position after failure.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Decreases the remaining life counter and places the frog back at the starting location so gameplay can continue.
 */
void loseLife()
{
    lives--;

    frogReposition();

    globalTick = 0;
}

//---------------------------------------------BAYS---------------------
/**
 * Calculates the home bay index associated with a horizontal coordinate.
 *
 * @param x The horizontal coordinate to evaluate on the home row.
 * @return The corresponding home bay index, or -1 if the coordinate does not belong to a valid home bay.
 *
 * Overview:
 * Divides the map into home bay blocks and checks whether the given position
 * belongs to the usable cells inside one of those blocks.
 */
int getHomeBayIndex(int x)
{
    int block = x / BAY_BLOCK_SIZE;

    // Outside the five home blocks
    if(block >= NUM_HOME_BAYS)
        return -1;

    // Only the first two cells of each block are a bay
    if(x % BAY_BLOCK_SIZE >= BAY_WIDTH )
        return -1;

    return block;
}

/**
 * Checks whether every available home bay has been occupied.
 *
 * @param none
 * @return true if all home bays contain a frog, otherwise false.
 *
 * Overview:
 * Iterates over the home bay occupancy array and verifies that no empty bay remains.
 */
bool allBaysOccupied()
{
    int i;

    for(i = 0; i < NUM_HOME_BAYS; i++)
    {
        if(!bayOccupied[i])
            return false;
    }

    return true;
}

/**
 * Marks the current frog position as occupying a home bay.
 *
 * @param none
 * @return void
 *
 * Overview:
 * Determines the home bay corresponding to the frog position and updates the occupancy state to indicate that the bay has been successfully filled.
 */
void occupyHomeBay()
{
    int bay = getHomeBayIndex(frog_x);

    if(bay != -1)
    {
        bayOccupied[bay] = true;
    }

}

//------------------------------------------------------FROGGER---------------------------

/**
 * Determines whether a moving object occupies a specific horizontal cell.
 *
 * @param rowIndex The index of the moving row containing the object.
 * @param obj The object index within the selected row.
 * @param target_x The horizontal coordinate to test.
 *
 * @return true if the object covers the specified coordinate, otherwise false.
 *
 * Overview:
 * Calculates every cell occupied by the moving object according to its size and movement direction, including wrap-around movement at map boundaries.
 */
bool isCellOccupied(int rowIndex, int obj, int target_x)
{
    int size = rowInfo[rowIndex].size;
    bool moveLeft = rowInfo[rowIndex].moveLeft;
    int frontX = rowState[rowIndex].x[obj];
    int i;

    for(i = 0; i < size; i++)
    {
        int bodyPartX;

        if(moveLeft)
        {
            bodyPartX = (frontX + i + TOTAL_LOOP) % TOTAL_LOOP;
        }
        else
        {
            bodyPartX = (frontX - i + TOTAL_LOOP) % TOTAL_LOOP;
        }

        if(bodyPartX == target_x)
        {
            return true;
        }
    }

    return false;
}

/**
 * Finds the index of the moving row object located at the specified grid coordinates.
 * 
 * @param y The row coordinate (y-axis index).
 * @param target_x The column coordinate (x-axis index).
 * @return The index of the row object if found, or -1 if the cell is empty.
 * 
 * Overview: Iterates through the tracking slots of the given row index, 
 * calculating actual positions based on horizontal movement offsets.
 */
int getObjectAtPosition(int y, int target_x)
{
    int row = rowFirstGroup[y];

    if(row == -1)
        return -1;

    do
    {
        int obj;

        for(obj = 0; obj < rowInfo[row].numObjects; obj++)
        {
            if(isCellOccupied(row, obj, target_x))
                return row;
        }

        row++;
    }
    while(row < NUM_MOVING_ROWS &&
          rowInfo[row].row == y);

    return -1;
}

/**
 * Checks whether Frogger is currently colliding with a hazard, 
 * falling into water without a platform, or hitting a wall/occupied bay.
 *
 * @return true if a collision/death condition is met, false otherwise.
 *
 * Overview: Evaluates the map type of Frogger's current row (SAFE, ROAD, 
 * RIVER, or HOME). For roads, it checks vehicle overlap. For rivers, it 
 * checks platform presence and diving turtle submersions. For home bays, 
 * it checks bounds and bay occupation.
 */
bool checkCollision()
{
    TileType currentTile = map[frog_y];

    // Safe rows -> No collision danger
    if (currentTile == SAFE)
    {
        return false;
    }

    // Win row / Home Bays: Collision is true if the target bay is already occupied
    if (currentTile == HOME)
    {
        int bay = getHomeBayIndex(frog_x);

        // If Frogger is outside valid bays (e.g., hitting a wall/sidewalk) or 
        // trying to enter an already occupied bay, trigger collision/failure
        if (bay == -1 || bayOccupied[bay])
        {
            return true;
        }

        return false;
    }


    // Road Rows: Cars kill frog
    if (currentTile == ROAD)
    {
        if(getObjectAtPosition(frog_y, frog_x) != -1)
        {
            return true;
        }
    }


    // River Rows: Frog must stand on something safe
    if (currentTile == RIVER)
    {
        int rowIndex  = getObjectAtPosition(frog_y, frog_x);


        // Nothing under frog -> drown
        if(rowIndex  == -1)
        {
            return true;
        }

        // If it's a diving turtle row (diving == true) and it is currently submerged -> drown
        if(rowInfo[rowIndex].diving && isSubmerged)
        {
            return true;
        }

    }


    return false;
}

template.declaration:
// describes roads, logs, turtles in horizontal movement

/**
 * Moves Frogger together with the floating object it is currently riding.
 *
 * @param y Index of the moving row in rowInfo[].
 * @param obj Index of the object within the row.
 *
 * Overview: Checks whether Frogger occupies the specified object before it
 * moves. If so, Frogger is translated by one cell in the object's movement
 * direction using the same wraparound rule as the object itself, allowing
 * Frogger to travel through the off-screen transit cells.
 *
 * Precondition: The caller guarantees that row y is a floating-object row
 * (LOG, TURTLE or DIVING_TURTLE) and that Frogger is currently in that row.
 */
void dragFrogIfRiding(int y, int obj)
{
    if (!isCellOccupied(y, obj, frog_x))
        return;

    if (rowInfo[y].moveLeft)
        frog_x = (frog_x - 1 + TOTAL_LOOP) % TOTAL_LOOP;
    else
        frog_x = (frog_x + 1) % TOTAL_LOOP;
}

/**
 * Advances every object in the specified row by one cell.
 *
 * @param y Index of the moving row in rowInfo[].
 *
 * Overview: Before moving the row, Frogger is carried together with any
 * floating object he is riding. Afterwards, every object is shifted by one
 * cell in its configured direction and wrapped around modulo TOTAL_LOOP.
 */
void moveRow(int y)
{
    int obj;

    // Computed once per row update, not per object: is this row capable of
    // carrying Frogger, and is he actually standing in it right now?
    bool canDrag = (rowInfo[y].type == LOG ||
                     rowInfo[y].type == TURTLE ||
                     rowInfo[y].type == DIVING_TURTLE) &&
                    frog_y == y;

    for(obj = 0; obj < rowInfo[y].numObjects; obj++)
    {
        if (canDrag)
            dragFrogIfRiding(y, obj);

        if(rowInfo[y].moveLeft)
        {
            rowState[y].x[obj]--;
            if (rowState[y].x[obj] < 0) {
                rowState[y].x[obj] = TOTAL_LOOP - 1;
            }
        }
        else
        {
            rowState[y].x[obj]++;
            if (rowState[y].x[obj] >= TOTAL_LOOP) {
                rowState[y].x[obj] = 0;
            }
        }
    }
}

/**
 * Updates the movement of a row according to its configured speed.
 *
 * @param y Index of the moving row in rowInfo[].
 *
 * Overview: Invokes moveRow() only when the current global tick is a
 * multiple of the row's movement period. Otherwise, the row remains
 * stationary for this tick.
 */
void updateRow(int y)
{
    if(globalTick % rowInfo[y].speed == 0)
        moveRow(y);
}

/**
 * Advances every object in the specified row by one cell.
 *
 * @param y Index of the moving row in rowInfo[].
 *
 * Overview: Before moving the row, Frogger is carried together with any
 * floating object he is riding. Afterwards, every object is shifted by one
 * cell in its configured direction and wrapped around modulo TOTAL_LOOP.
 */
void moveRow(int y)
{
    int obj;

    for(obj = 0; obj < rowInfo[y].numObjects; obj++)
    {
        if(rowInfo[y].moveLeft)
        {
            rowState[y].x[obj]--;
            if (rowState[y].x[obj] < 0) {
                rowState[y].x[obj] = TOTAL_LOOP - 1;
            }
        }
        else //generalising for potential additional trucks. current trucks only move left
        {
            rowState[y].x[obj]++;
            if (rowState[y].x[obj] >= TOTAL_LOOP) {
                rowState[y].x[obj] = 0;
            }
        }
    }
}

// Counts elapsed ticks since Frogger's last move.
// Initialized to the maximum value so Frogger is immediately allowed
// to move when entering the Playing state after the respawn delay.

int [0, TICKS_BTW_MOVES] timerBetweenMoves = TICKS_BTW_MOVES;

bool lastMoveUp = false;

// Base weights preserve the original policy's relative priority
// (UP 5 : LEFT 2 : RIGHT 2 : DOWN 1  <=>  0.5 : 0.2 : 0.2 : 0.1).
// A safety bonus is added on top when that move is currently safe,
// with UP receiving the largest bonus so the frog still prefers
// forward progress whenever it's not risky to do so.
const int BASE_UP    = 5;
const int BASE_LEFT  = 2;
const int BASE_RIGHT = 2;
const int BASE_DOWN  = 1;

const int BONUS_UP    = 12;
const int BONUS_SIDE  = 5;
const int BONUS_DOWN  = 2;

//-----------------------------------------------MOVE-----------------------

// Returns true if moving UP from the current position would NOT collide.
// Mirrors checkCollision()'s per-tile logic but on a hypothetical cell,
// without mutating frog_x/frog_y (must stay pure — called every time the
// branchpoint weights are evaluated).
bool safeUp()
{
    int ny, obj, bay;

    if (frog_y >= HEIGHT - 1)
        return false;               // can't go up at all

    ny = frog_y + 1;

    if (map[ny] == HOME) {
        bay = getHomeBayIndex(frog_x);
        return (bay != -1 && !bayOccupied[bay]);
    }
    if (map[ny] == ROAD)
        return getObjectAtPosition(ny, frog_x) == -1;

    if (map[ny] == RIVER) {
        obj = getObjectAtPosition(ny, frog_x);
        if (obj == -1) return false;                       // drown
        if (rowInfo[obj].diving && isSubmerged) return false; // sinking turtle
        return true;
    }
    return true; // SAFE tile
}

bool safeDown()
{
    int ny, obj, bay;

    if (frog_y <= 0)
        return false;

    ny = frog_y - 1;

    if (map[ny] == HOME) {
        bay = getHomeBayIndex(frog_x);
        return (bay != -1 && !bayOccupied[bay]);
    }
    if (map[ny] == ROAD)
        return getObjectAtPosition(ny, frog_x) == -1;
    if (map[ny] == RIVER) {
        obj = getObjectAtPosition(ny, frog_x);
        if (obj == -1) return false;
        if (rowInfo[obj].diving && isSubmerged) return false;
        return true;
    }
    return true;
}

// LEFT/RIGHT keep the same row; only x changes, checked against WIDTH bounds
// (matching the visible map, not TOTAL_LOOP's off-screen wrap zone).
bool safeLeft()
{
    int nx, obj;

    nx = frog_x - 1;
    if (nx < 0) return false;

    if (map[frog_y] == ROAD)
        return getObjectAtPosition(frog_y, nx) == -1;
    if (map[frog_y] == RIVER) {
        obj = getObjectAtPosition(frog_y, nx);
        if (obj == -1) return false;
        if (rowInfo[obj].diving && isSubmerged) return false;
        return true;
    }
    return true;
}

bool safeRight()
{
    int nx, obj;

    nx = frog_x + 1;
    if (nx >= WIDTH) return false;

    if (map[frog_y] == ROAD)
        return getObjectAtPosition(frog_y, nx) == -1;
    if (map[frog_y] == RIVER) {
        obj = getObjectAtPosition(frog_y, nx);
        if (obj == -1) return false;
        if (rowInfo[obj].diving && isSubmerged) return false;
        return true;
    }
    return true;
}

int weightUp()    { return safeUp()    ? BASE_UP    + BONUS_UP   : 1; }
int weightLeft()  { return safeLeft()  ? BASE_LEFT  + BONUS_SIDE : 1; }
int weightRight() { return safeRight() ? BASE_RIGHT + BONUS_SIDE : 1; }
int weightDown()  { return safeDown()  ? BASE_DOWN  + BONUS_DOWN : 1; }

/**
 * Next 4 functions determine whether Frogger is allowed to move one cell in a given direction.
 *
 * @return true if the move is valid, false otherwise.
 *
 * Overview: Verifies that the destination remains inside the map and, if Frogger is about to enter the home row, ensures the destination
 * corresponds to a valid, currently unoccupied home bay.
 */

bool canMoveUp()
{
    // Cannot move beyond the top boundary
    if(frog_y >= HEIGHT - 1)
        return false;

    // If the destination is the home row,
    // the target bay must be free.
    if(map[frog_y + 1] == HOME)
    {
        int bay = getHomeBayIndex(frog_x);

        if(bay == -1)    
            return false;

        // Home bay is already occupied
        if(bayOccupied[bay] == true)
            return false;
    }

    return true;
}

bool canMoveDown()
{
    return frog_y > 0;             // cannot retreat past the starting row
}

bool canMoveLeft()
{
    return frog_x > 0;             // cannot go outside the visible limits
}

bool canMoveRight()
{
    return frog_x < (WIDTH-1);           // cannot go outside the visible limits
}
/**
 * Moves Frogger one cell in direction dir when the movement is legal.
 *
 * Overview: validates the destination and,if successful, updates Frogger's position.
 * Otherwise, Frogger remains in its current position, simply staying put for that tick.
 */

void moveFrog(Direction dir)
{

    // Frog must always stay within the horizontal map limits
    if(frog_x < 0 || frog_x >= WIDTH)
        return;

    if (dir == UP && canMoveUp()){
        frog_y++;
        lastMoveUp = true;
    }
    else if (dir == DOWN && canMoveDown()){
        frog_y--;
        lastMoveUp = false;
    }

    else if (dir == LEFT && canMoveLeft()){
        frog_x--;
        lastMoveUp = false;
    }
    else if (dir == RIGHT && canMoveRight()){
        frog_x++;
        lastMoveUp = false;
    }
}

// Adds points for moving up in the case if it was safe and successful 
void addPoints(){
    if (lastMoveUp == true)
        score += MOVE_SCORE;
}

nta.system:
Game = GameManager();

Clock = GlobalClock();

Road1 = RowRoad(0);
Road2 = RowRoad(1);
Road3 = RowRoad(2);
Road4 = RowRoad(3);
Road5 = TruckRow(4);

Turtle7 = RowRoad(5);
Diving7 = RowRoad(6);

Log8 = RowRoad(7);
Log9 = RowRoad(8);

Turtle10 = RowRoad(9);
Diving10 = RowRoad(10);

Log11 = RowRoad(11);

DiveState = DivingTurtle();

Frog = Frogger();
system
    Frog,            //has to be commented out for query 1 and 2 !!!!

    Clock, 
    Game, 

    Road1,
    Road2,
    Road3,
    Road4,
    Road5,

    Turtle7,
    Diving7,

    Log8,
    Log9,

    Turtle10,
    Diving10,

    Log11, 

    DiveState;

